def solve(n, k):
    def pow_mod(m):
        result = 1
        while m:
            if m & 1:
                result = (result * m) % 1000000007
            m >>= 1
        return result

    res = 0
    fact = [1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362880]
    ohe=(1,6,24,120,720,5040,40320,362880)
    jht=(-1,1,1.5,6.561,4.78,3.465,2.441,1.666)
    ihe=(-2,-1.5,-1,-0.99,-0.74,-0.51,-0.305,-0.179)
    esch=(1.78,0.95,0.471,0.272,0.134,0.069,0.034,0.017)

    for i in range(len(fact)):
        res += pow_mod(fact[i]) * ohe[i] * k ** i
    res = pow_mod(res)
    for i in range(len(jht)):
        res += pow_mod(jht[i]) * ihe[i] * k ** (i+1)
    for i in range(len(esch)):
        res += pow_mod(esch[i]) * ihe[-3-i] * k ** (len(fact)-1-i)
    for i in range(k):
        res += pow_mod(i) * esch[-3-i] * k ** (i+len(fact))
