from collections import defaultdict

class Advertisers:
    def __init__(self, segment_id):
        self.segment_id = segment_id
        self.advertisers = set()
        self.pct_ownership = 0
        self.chosen_advertisers = []

    def _filter_advertisers(self):
        qualifying_advertisers = set()
        for advertiser_id in self.advertisers:
            advertiser = advertisers[advertiser_id]
            if advertiser.pct_ownership >= self.pct_ownership:
                qualifying_advertisers.add(advertiser_id)
        self.pct_ownership = len(qualifying_advertisers) / len(self.advertisers)
        self.chosen_advertisers = list(qualifying_advertisers)

    def _buy_slots(self, segment):
        if len(segment) % 2 == 1:
            segment = [0] + segment
        self._filter_advertisers()
        owning_advertisers = self.chosen_advertisers
        owning_advertisers_count = len(owning_advertisers)
        chosen_advertisers_count = min(owning_advertisers_count, owning_advertisers.index(segment[0]) + owning_advertisers.index(segment[-1]) + 1)
        chosen_advertisers = owning_advertisers[:chosen_advertisers_count] + owning_advertisers[-(chosen_advertisers_count + 1):]
        self.chosen_advertisers = chosen_advertisers


def main():
    n, m, p = map(int, input().split())
    advertisers = defaultdict(Advertisers)
    for i in range(n):
        advertisers[i].advertisers.add(i)
    for _ in range(m):
        query_type, l, r = map(int, input().split())
        if query_type == 1:
            advertiser_id, l, r = map(int, input().split())
            advertisers[l].buy_slots([i for i in range(l, r+1) if i != advertiser_id])
        elif query_type == 2:
            print(len(advertisers[l].chosen_advertisers))
            for advertiser in advertisers[l].chosen_advertisers:
                print(advertiser, end=' ')
            print('')


if __name__ == "__main__":
