def find_last_point(n, b, rules, ti, initial_xi, initial_xi_u):
    last_points = []
    last_point = (0, 0)
    last_flag = True

    def update_coords(point, xi, flag, yi):
        nonlocal last_point
        nonlocal last_flag
        if point[0] == 0 and point[0] == yi:
            last_flag = False
            if point[1] == yi:
                last_point = point
            else:
                last_point = (point[0] - 1, point[1])

    for rule in rules:
        x0, y0 = rule[0], rule[1]
        x1, y1 = rule[2], rule[3]

        if x0 >= x1:
            update_coords(x0, x1, initial_xi_u)
        else:
            update_coords(x0, xi, initial_xi_u)
        if y0 >= y1:
            update_coords(y0, y1, initial_xi_u)
        else:
            update_coords(y0, yi, initial_xi_u)

        if not last_flag:
            break

    points_to_check = list(zip((initial_xi, initial_xi), (initial_xi_u, initial_xi_u)))
    for _ in range(ti):
        points_to_check = [point + rule for point, rule in zip(points_to_check, points_to_check)]

    for point in points_to_check:
        x, y = point   
        for i in range(n):
            if abs(x - rules[i][0]) > abs(y - rules[i][1]):
                x_mod = (x - rules[i][0] * n) % n + rules[i][0]
            else:
                y_mod = (y - rules[i][1] * n) % n + rules[i][1]
            if x_mod >= 0:
                index_remix = list(range(len(rules)))
                for index in range((len(rules) - (rules[i][0] < x_mod or rules[i][1] < y_mod))):
                    del index_remix[index - len(rules) + 1]
                if list(index_remix)[0][0] + n != rules[i][0]:
                    index_free = ((rules[i][0] % n + 1) / n) * i + 1
                    index_free = int(index_free) * n + list(index_remix)[0][1]
                    break

        for i in range(n):
            if abs(x - index_free) > abs(y - index_free):
                x_mod = (x_prime - index_free + n) % n + index_free
            else:
                y_mod = (y_prime - index_free) % n + index_free
            if x_mod >= 0:
                index_remix = list(range(len(rules)))
                for index in range((len(rules) - (rules[i][0] < x_mod or rules[i][1] < y_mod))):
                    del index_remix[index - len(rules) + 1]
                if list(index_remix)[0][0] + n != rules[i][0]:
                    index_free = int((rules[i][0] % n + 1) / n)
                    index_free = (index_free - index + 1) * n + list(index_remix)[0][1]
                    break

        x_prime, y_prime = x_mod, y_mod
        last_points.append((x_prime, y_prime))

    if last_flag:
        last_points.append(last_point)

    for i in range(len(last_points)):
        last_points[i] = sorted(last_points[i])
        while last_points[i] != tuple(sorted(last_points[i])):
            last_points[i] = last_points[i][1:]

        last_points[i] = (last_points[i][0] % n + 1, rules[last_points[i][0] % n - 1][1])

    return last_points

if __name__ == "__main__":
