def get_cumulative_minmax(ti, events, params):
    heapq.heappush(priority_queue, (-ti, ti-1))  # Prioritize larger values for tornadoes
    minmaxes = [None for _ in range(len(params))]
    time = -priority_queue[0][1]

    for event in events:
        if event > 0:
            perturbation_index = event - 1
            while minmaxes[perturbation_index] < time:
                heapq.heappop(priority_queue)
                time -= 1
        else:
            perturbation_index = -event - 1
            current_time = time
            dbtl_index = ti
            while dbtl_index and dbtl_index <= current_time:
                heapq.heappop(priority_queue)
                dbtl_index -= 1
            if priority_queue:
                minmaxes[perturbation_index] = priority_queue[0][0]
            else:
                minmaxes[perturbation_index] = None

    return minmaxes

