            n //= i
        i += 1
    if n != 1:
        factors.append(n)
    return factors

def binary_exponentiation(a, b):
    if b < 0:
        raise Exception('negative exponent cannot be used in bitwise operations...')
    elif b < 2:
        res = 1
        for _ in range(min(1, b)):
            res = res * a % MODPI
        return res
    else:
        m = 1
        res = 1
        while (b > m):
            if b % 2 == 0:
                a = a * a % MOD
                b = b // 2
            m = m * 2
            res = res * a % MOD
            b -= m

        return res * binary_exponentiation(a, min(b, m)) % MODPI

def multiply(x, y):
    if y < 0:
        return multiply(y, x)
    if (y % 2) == 1:
        return (x * y) % MOD
    return multiply(binary_exponentiation(x, 2), power(y) * (1 - x) % MOD)

def xfsum(x):
