def power(x, y):
    ans = 1
    while (y > 0):
        if y % 2 == 1:
            ans = multiply(power(x,y // 2), x) % MODPI
        y //= 2 
        x = binary_mod(x, y)
    return ans % MODPI

def binary_mod(x, y):
    if y < 0:
        return 0

    elif x == 0:
        return 0

    elif y % 2 == 0: 
        return binary_mod(binary_mod(x,y//2) * binary_mod(x,y//2) % MODPI, y//2)

    else:
        return (binary_mod(x,y//2) * power(x,y//2) * binary_mod(x,y//2) * binary_mod(y,y//2) % MODPI, y//2) 

