def calculate_potential(cores):
    potential = 0
    for i in range(len(cores)):
        pot = 0
        for j in range(len(cores)):
            if j != i and cores[j] in cores[i]:
                pot += 1
        potential += pot
    return potential

def maximize_potential(edges):
    cores = set(range(len(edges)))
    start_cores = set()
    max_potential = 0
    for start_core in cores:
        for i in range(len(edges)):
            if i not in cores:
                potential = calculate_potential(get_connected_cores(edges, cores.difference([start_core])))
                if potential > max_potential:
                    max_potential = potential
                    start_cores = {start_core}
                elif potential == max_potential and start_core not in start_cores:
                    start_cores.add(start_core)
    return max_potential

