# Function to calculate Euler's Totient function for a given prime factorization
def euler_totient(k1, k2, k3):
    # Calculate lcm for any given prime powers
    def lcm(a, b):
        return a * b / math.gcd(a, b)

    # Calculate lcm and gcd for each prime factor power
    result = 1
    for k in [k1, k2, k3]:
        result *= k / math.gcd(k, result)
    # Reduce by lcm of any two primes
    for i in range(2, min(k1, k2, k3)+1):
        result //= math.gcd(result, i)
    return int(result)

# Get number of elegant numbers up to n
def count_elegant_numbers(n):
    count = 0
    for k1 in range(1, int(math.log2(math.sqrt(n))) + 3):
        for k2 in range(k1 + 1, int(math.log(math.sqrt(n) // 3 ** k1)) + 3):
            for k3 in range(k2 + 1):
                prime_factors_power = [2**k1, 3**k2, 5**k3]
