def min_swaps_to_unbalance(s):
    balance = 0
    max_balance = 0
    unbalanced_index = None

    for i, char in enumerate(s):
        if char == '(':
            balance += 1
            if balance > max_balance:
                max_balance = balance
                unbalanced_index = i
        else:
            balance -= 1

    if balance == 0 or unbalanced_index is None:
        return 0

    # Find the neighbor of the unbalanced index
    unbalanced_index_start = unbalanced_index - 1
    unbalanced_index_end = unbalanced_index

    if unbalanced_index_start >= 0:
        unbalanced_index_start = s[unbalanced_index_start] == '(' and unbalanced_index_start or unbalanced_index_start - 1
    if unbalanced_index_end < len(s) - 1:
        unbalanced_index_end = s[unbalanced_index_end] == ')' and unbalanced_index_end or unbalanced_index_end + 1

    if unbalanced_index_start == -1 and unbalanced_index_end == len(s):
        return len(s)

    # Swap the unbalanced segments
    return len(s) - (s[unbalanced_index_start] == '}' and unbalanced_index_start or unbalanced_index_start - 1) - (s[unbalanced_index_end] == '{' and unbalanced_index_end or -1 - unbalanced_index_end) - 1

