    max_children = [n] * n

    # Get the adjacency list of the parent of each vertex in the tree
    for i, children in enumerate(tree):
        for child in children:
            tree[i].append((child, i+1))

    # Use an adjacency list to determine from which parents I can draw edges
    adj_parents = defaultdict(list)
