            for x, y in children:
                adj_parents[i+1].append((y+1, i+1))

    # Build a table with each child's farthest dependence on parents plus 1
    farthest_parents = [len(i)+1 for i in adj_parents.values()]

    # Dijkstra's Algorithm to determine the maximum c(v) for each vertex
