from math import gcd
from functools import reduce

MOD = 998244353

def prime_factors(n):
    factors = []
    for factor in range(2, int(n**0.5) + 1):
        while n % factor == 0:
            factors.append(factor)
            n //= factor
    if n > 1:
        factors.append(n)
    return factors

def prime_power_factors(N):
    factors = []
    for i in range(2, int(N**0.5) + 1):
        if N % i == 0:
            while N % i == 0:
                N //= i
            factors.append(i)
    if N > 1:
        factors.append(N)
    return factors

def sum_of_digits(n):
    return sum(int(digit) for digit in str(n))

def count_good_divisions(N, pairs):
    total_matches = 0
    num_players = sum(neuron[1] for neuron in pairs)
    for neuron in pairs:
        num_skill_level = sum(neuron[1])
        prime_factors_list = prime_factors(num_skill_level)
        num_prime_factors = len(prime_factors_list)

        # Calculate total matches for the current team formation
        total_matches += sum(sum_of_digits(prime_power_factors(n)) % MOD for n in range(num_prime_factors + 1, num_players + 1))

    return total_matches % MOD

