from collections import defaultdict

def lcs(s1, s2):
    dp = [[0] * (len(s2)+1) for _ in range(len(s1)+1)]
    for i in range(len(s1)-1, -1, -1):
        for j in range(len(s2)-1, -1, -1):
            if s1[i] == s2[j]:
                dp[i][j] = dp[i+1][j+1] + 1
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j+1])
    return dp[0][0]

def count_sequences(n, m, p):
    if n == 1:
        return m % p
    if n == 2:
        sum = 0
        for i in range(1, m):
            sum += lcs('01'*i, '01'*i[::-1]) % p
        return sum % p
    last_counts = defaultdict(lambda: [0] * 100)
    for i in range(p):
        last_counts[i][0] = last_counts[i][-1] = 1
    for i in range(1, n-1):
        new_counts = defaultdict(lambda: [0] * 100)
        for current in range(p):
            result = 0
            for i in range(100):
                if i == 0 or i == 99:
                    result = (result + last_counts[current][i] - last_counts[current][99-i]) % p
                else:
                    result = (result + last_counts[current][i] * (1 + last_counts[current][(i-1)//2] * last_counts[current][(i-1)%2])) % p
                new_counts[current][i] = result
        last_counts = new_counts
    ans = 0
    for i in range(p):
        for j in range(1, 5001):
            ans = (ans + last_counts[i][j] * last_counts[i][5000-j]) % p
    return ans

