def tupleset(tup, vals):
    if len(set(tup)) != len(tup):
        return []
    t = list(tup)
    ans = t[:]
    for v in vals:
        for i, p in enumerate(list(ans).copy()):
            if p == v:
                ans[i] = None
    for p in ans:
        if p is not None:
            ans.remove(p)
    return tuple([v for v in ans if v is not None])

def prune(p, s, e, y):
    ans = []
    for el in list(p):
        if el == s or el == e:
            continue
        ans.append((el[0] + y, el[1] + y))
    return tuple(ans)

