                    G[j] = G[i].pop()

        current_sum, duplicate = 0, defaultdict(int)
        for s in G[node]:
            if not s == parent:
                DFS1(s)
                add_path(s, node)
                current_sum += s + duplicate[node]
                duplicate[s] += 1
        duplicates = filter(lambda x: x > 1, duplicate.values())
        current_sum -= sum(duplicates)
        return G[node], current_sum + current_sum // 2

    def DFS1(u):
        nonlocal current_sum
        G[u], current_sum_v = dfs(u)
        current_sum += (current_sum_v - (current_sum_v // 2) * deg[u])

    DFS1(1)
    add_path(1, n)
    DFS1(n)
    return DEG

n = int(input())
DEG = max_deg_sum(n)
